#include <iostream>

int main() {
    // Floating-point forms
    double fixedPi = 3.1416;
    double sciPi = 0.31416e1;

    // Character representations of 'A'
    char c1 = 'A';
    char c2 = '\101'; // Octal
    char c3 = '\x41'; // Hex

    // Distinguishing '3' vs "3"
    char charThree = '3';
    const char* strThree = "3";

    std::cout << fixedPi << " " << sciPi << "\n";
    std::cout << c1 << " " << c2 << " " << c3 << "\n";
    std::cout << int(charThree) << " " << strThree[0] << "\n";
    return 0;
}

#include <iostream>

// Compile-time constant definition
constexpr int MAX_STUDENTS = 50;

int main() {
    // Typed constant
    const double BOILING_POINT = 100.0;

    // Variable declared right when needed
    int currentStudents = 45;
    std::cout << "Remaining: " << (MAX_STUDENTS - currentStudents) << "\n";

    // Variable value modification
    currentStudents = currentStudents + 3;
    std::cout << "Updated: " << currentStudents << "\n";
    std::cout << "Boiling temp: " << BOILING_POINT << "\n";

    return 0;
}
